using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;using System.Collections.Generic;
public static class RoomSwitchMounting {
 static float Hit(GameObject root,Ray ray){float best=float.PositiveInfinity;foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true)){if(!mf.gameObject.activeInHierarchy||mf.sharedMesh==null||!mf.name.Contains("Wall")&&!mf.transform.GetComponentsInParent<Transform>().Any(t=>t.name=="Wall"||t.name=="Authored Architecture"))continue;var renderer=mf.GetComponent<MeshRenderer>();if(renderer==null)continue;var mesh=mf.sharedMesh;var v=mesh.vertices;for(int sub=0;sub<mesh.subMeshCount;sub++){var mats=renderer.sharedMaterials;if(sub>=mats.Length||mats[sub]==null||mats[sub].name=="Transparent")continue;var tris=mesh.GetTriangles(sub);for(int i=0;i<tris.Length;i+=3){var a=mf.transform.TransformPoint(v[tris[i]]);var e1=mf.transform.TransformPoint(v[tris[i+1]])-a;var e2=mf.transform.TransformPoint(v[tris[i+2]])-a;var p=Vector3.Cross(ray.direction,e2);float det=Vector3.Dot(e1,p);if(det<1e-7f)continue;var t=ray.origin-a;float u=Vector3.Dot(t,p)/det;if(u<0||u>1)continue;var q=Vector3.Cross(t,e1);float w=Vector3.Dot(ray.direction,q)/det;if(w<0||u+w>1)continue;float d=Vector3.Dot(e2,q)/det;if(d>=0&&d<best)best=d;}}}return best;}
 public static string Run(bool repair=false){if(Application.isPlaying)throw new Exception("Run in Edit Mode");var output=new List<string>();int count=0,changed=0;foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Building"})){var path=AssetDatabase.GUIDToAssetPath(guid);var root=PrefabUtility.LoadPrefabContents(path);bool dirty=false;try{foreach(var s in root.GetComponentsInChildren<LightSwitchInteractable>(true)){count++;var mf=s.GetComponent<MeshFilter>();if(mf==null)throw new Exception("Missing backplate "+path);var mesh=mf.sharedMesh;float back=mesh.vertices.Min(v=>v.z);var b=mesh.bounds;var backPoint=mf.transform.TransformPoint(new Vector3(b.center.x,b.center.y,back));var forward=mf.transform.forward;float distance=Hit(root,new Ray(backPoint+forward,-forward));if(float.IsInfinity(distance)||Mathf.Abs(distance-1)>1)throw new Exception("No supporting wall "+path);float gap=distance-1;output.Add(root.name+" backplate gap="+gap.ToString("F5"));if(repair&&Mathf.Abs(gap-.001f)>.0002f){s.transform.position+=forward*(.001f-gap);dirty=true;changed++;}
 foreach(var x in new[]{-.7f,0,.7f})foreach(var y in new[]{-.7f,0,.7f}){var point=mf.transform.TransformPoint(new Vector3(b.center.x+b.extents.x*x,b.center.y+b.extents.y*y,back));float d=Hit(root,new Ray(point+forward,-forward))-1;if(repair&&Mathf.Abs(d-.001f)>.002f)throw new Exception("Backplate unsupported "+root.name+" gap="+d);if(!repair&&Mathf.Abs(d-.001f)>.002f)throw new Exception("Backplate not flush "+root.name+" gap="+d);}}
 if(dirty){Directory.CreateDirectory("Temp/SwitchMountingBackup");var backup="Temp/SwitchMountingBackup/"+Path.GetFileName(path);if(!File.Exists(backup))File.Copy(path,backup);PrefabUtility.SaveAsPrefabAsset(root,path);}}finally{PrefabUtility.UnloadPrefabContents(root);}}AssetDatabase.SaveAssets();return count+" switches checked, "+changed+" adjusted\n"+string.Join("\n",output);}
}


